require_once __DIR__.'/../app/layout.php';if($_SERVER['REQUEST_METHOD']==='POST'){require_role('candidate');verify_csrf();$title=trim($_POST['title']??'');$cat=trim($_POST['category']??'Lainnya');$desc=trim($_POST['description']??'');$price=filter_var($_POST['price']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>0]]);$portfolio=trim($_POST['portfolio_url']??'');if(mb_strlen($title)<4||mb_strlen($desc)<20||$price===false){flash('error','Lengkapi judul, deskripsi minimal 20 karakter, dan harga yang valid.');redirect('freelance.php');}$st=db()->prepare("INSERT INTO freelance_services(user_id,title,category,description,price,portfolio_url) VALUES(?,?,?,?,?,?)");$st->execute([current_user()['id'],$title,$cat,$desc,$price,$portfolio]);flash('success','Jasa berhasil dipublikasikan.');redirect('freelance.php');}
$q=trim($_GET['q']??'');$sql="SELECT f.*,u.name FROM freelance_services f JOIN users u ON u.id=f.user_id WHERE f.status='Aktif'";$p=[];if($q!==''){$sql.=' AND (f.title LIKE ? OR f.category LIKE ? OR f.description LIKE ?)';$v="%$q%";array_push($p,$v,$v,$v);}$sql.=' ORDER BY f.created_at DESC';$st=db()->prepare($sql);$st->execute($p);$list=$st->fetchAll();page_header('Jasa freelance','freelance');?>
<section class="page-hero"><div class="container"><span class="eyebrow">KEAHLIANMU PUNYA NILAI</span><h1>Temukan jasa. Tawarkan karya.</h1><p>Ruang untuk memamerkan keahlian dan menemukan peluang proyek profesional.</p></div></section><section class="section"><div class="container"><div class="toolbar"><form method="get" class="search-inline"><label class="sr-only" for="q">Cari jasa</label><input id="q" name="q" value="<?=e($q)?>" placeholder="Cari desain, penulisan, pemrograman..."><button class="btn btn-primary">Cari</button></form><?php if(current_user()&&current_user()['role']==='candidate'):?><button type="button" class="btn btn-dark" data-open-form="service-form">+ Tawarkan jasa</button><?php else:?><a class="btn btn-dark" href="<?=e(url('register.php'))?>">Daftar untuk menawarkan jasa</a><?php endif;?></div><?php if(current_user()&&current_user()['role']==='candidate'):?><div id="service-form" class="panel" hidden><h2>Publikasikan jasa</h2><form method="post" class="form"><?=csrf_field()?><label>Nama jasa<input name="title" required placeholder="Pembuatan landing page"></label><div class="form-row"><label>Kategori<select name="category"><?php foreach(['Desain','Pemrograman','Penulisan','Administrasi','Pemasaran digital','Lainnya'] as $c):?><option><?=$c?></option><?php endforeach;?></select></label><label>Harga mulai (Rp)<input type="number" name="price" min="0" required></label></div><label>Deskripsi jasa<textarea name="description" rows="3" minlength="20" required></textarea></label><label>Link portofolio<input type="url" name="portfolio_url" placeholder="https://..."></label><button class="btn btn-primary">Publikasikan jasa</button></form></div><?php endif;?><div class="service-grid"><?php foreach($list as $s):?><article class="service"><div class="service-cover"><span><?=e(initials($s['name']))?></span><small><?=e($s['category'])?></small></div><div class="service-body"><small class="company-name"><?=e($s['name'])?></small><h3><?=e($s['title'])?></h3><p><?=e(mb_strimwidth($s['description'],0,140,'…'))?></p><div class="service-bottom"><div><small>Harga mulai</small><b>Rp <?=number_format((int)$s['price'],0,',','.')?></b></div><?php if($s['portfolio_url']):?><a class="btn btn-outline btn-sm" href="<?=e($s['portfolio_url'])?>" target="_blank" rel="noopener">Portofolio ↗</a><?php endif;?></div></div></article><?php endforeach;?></div><?php if(!$list):?><div class="empty"><h2>Belum ada jasa yang cocok</h2><p>Coba kata kunci lain atau jadilah yang pertama menawarkan keahlian.</p></div><?php endif;?><p class="tiny">Marketplace ini menampilkan katalog jasa. Pembayaran dan perlindungan transaksi perlu diintegrasikan sebelum penggunaan komersial.</p></div></section><?php page_footer();?>
